/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.context.props.payload.pageParams.channel == 'messenger') {
        return 'Manage your self-configured bot with your Messenger channel'
    }
    else if (api.context.props.payload.pageParams.channel == 'line') {
        return 'Manage your self-configured bot with your Line channel';
    }
}
